import{_ as a,o as t,c as r,a5 as n}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"了解排行榜与竞赛","description":"","frontmatter":{"title":"了解排行榜与竞赛","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"zh","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"dcf08e4ef08a28fc3e32216b2017b5f208afc57a91e537fd3b90a6f0ed1f041e","translationRevision":"7efb2f20a170e42ae53d494e5e48a44dbfa7f3bd0fbe4d4192b558626493e8b9","order":30},"headers":[],"relativePath":"zh/user/points/rankings.md","filePath":"zh/user/points/rankings.md","lastUpdated":1794611623000}'),i={name:"zh/user/points/rankings.md"};function o(s,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="understand-rankings-and-competitions" tabindex="-1">了解排行榜与竞赛 <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to &quot;了解排行榜与竞赛 {#understand-rankings-and-competitions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>选择合适的排名视图，并了解仍在开发的排行榜工作区有哪些限制。有意义的分数需要传入活动。如果只是查看当前观众，请先使用常规<a href="./rules.html">积分</a>榜或<a href="./../live/feed.html">直播事件流</a>中的热门观众面板。</p><h2 id="use-the-right-view" tabindex="-1">使用合适的视图 <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to &quot;使用合适的视图 {#use-the-right-view}&quot;">​</a></h2><ol><li>在 <strong>积分</strong> 中搜索观众，按积分、等级或观众身份排序。比较手动调整与奖励前，先刷新。</li><li>在 <strong>实时动态</strong> 中检查可用的观众排名面板。它们可以独立于积分余额表，接收排名引擎快照。</li><li>需要叠加层时，打开 <a href="./../overlays/">叠加层</a>，选择排行榜类型并检查来源选项。必须先存在已配置的排名来源，才能显示其输出。</li></ol><p>专门的 <strong>排名与竞赛</strong> 工作区仍属实验性功能。其前端路由为 <code>#/rankings</code>，但它被有意隐藏于主导航之外，也不会恢复为启动标签页。侧栏没有该条目，不表示路由或排名引擎已移除。</p><h2 id="configure-an-experimental-ranking" tabindex="-1">配置实验性排行榜 <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to &quot;配置实验性排行榜 {#configure-an-experimental-ranking}&quot;">​</a></h2><p>如果环境提供该工作区，请从一个主播、一个直播间、按用户分组及会话窗口开始。添加一个已声明的指标，例如 <code>tiktok.like</code> / <code>like.count</code>，权重设为 <code>1</code>。设置适中的结果上限，并创建定义。表单也支持滚动和每日窗口，可明确设置时长/事件界限或时区偏移。</p><p>引入更多来源前，先阅读生成的快照。暂停与恢复影响排名收集；重置会有意清空排名状态。竞赛选项和投票相关来源有各自的分组规则。不要假定重置积分也会重置竞赛，或所有自定义分组都适用于所有指标。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>常规排行榜可用，专用管理页面仍属实验性。分数来自宿主，不是通过统计显示的事件行得出。本指南不能证明真实直播/OBS 或每种竞赛组合都已通过验收。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>分数持续为空时，检查主播、直播间、来源启用状态、窗口及暂停状态。移除不受支持的来源/分组组合，不要编造字段名。重置前通过<a href="./../preferences/backups.html">备份</a>保存重要数据；报告问题时附上定义 ID 与诊断代码。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>Points 表格请求 100 位观众，只对收到的行搜索和排序。刷新或按姓名排序不会搜索整个数据库。动态流榜单按主播/房间会话显示 10 行：Top 统计礼物钻石，Likes 统计点赞数量，最多跟踪 5,000 位观众。这些榜单不表示已保存积分。比较总数前，请先确认单位及会话范围。</p>',15)])])}const f=a(i,[["render",o]]);export{p as __pageData,f as default};
